const path = require('path');
const assert = require('assert');
const fs = require('fs');
const execSync = require('child_process').execSync;

const syncfile = require('../lib/jibo-syncignore');

// This is a set of fake test packages used in the automated testing of jibo-syncignore.
// The idea is that syncingore should correctly identify the development dependencies and
// add them to the .autoignore file. The same should be true for the development dependencies
// of the production dependencies. The production dependencies themselves should be not be added.
//
// Dependency structure
//
// package1
// |_ shared
// |_ dev1 *
// |  |_ dev1-1 *
// |  |_ dev1-2 *
// |  |_ dev1-prod1
// |  |_ shared
// |_ dev2 *
// |  |_ dev2-1 *
// |  |_ dev2-prod1
// |_ prod1
//    |_ prod1-1
//    |_ prod1-2
//       |_ prod1-2-dev1 *
//
// package2
// |_ devA
// |_ prodA
// |_ package1 [via symlink]
//
// * = dev dependency


describe('jibo-syncignore', function(){
    // SyncIgnore can take a while
    this.timeout(30000);

    before(function(){
        const target = path.join(__dirname, 'input/package2/node_modules');
        const link = path.relative(target, path.join(__dirname, 'input/package1'));
        const symlink = path.join(target, 'package1');

        // Remove the symlink from package2
        if (fs.existsSync(symlink)) {
            fs.unlinkSync(symlink);
        }
        this.symlink = symlink;
        execSync('npm link ' + link, { cwd: target });
    });

    after(function(){
        fs.unlinkSync(this.symlink);
        delete this.symlink;
    });

    it('Should resolve dev dependencies in a package', function(){
        const dir = path.join(__dirname, 'input/package1');
        const syncignore = new syncfile.SyncIgnore(dir);
        const packages = syncignore.exec(true);
        assert(packages.length === 8);
        assert(packages.indexOf("/node_modules/@jibo/dev1") > -1);
        assert(packages.indexOf("/node_modules/@jibo/dev1-1") > -1);
        assert(packages.indexOf("/node_modules/@jibo/dev1-2") > -1);
        assert(packages.indexOf("/node_modules/@jibo/dev1-prod1") > -1);
        assert(packages.indexOf("/node_modules/@jibo/dev2") > -1);
        assert(packages.indexOf("/node_modules/@jibo/dev2-1") > -1);
        assert(packages.indexOf("/node_modules/@jibo/dev2-prod1") > -1);
        assert(packages.indexOf("/node_modules/@jibo/prod1-2-dev1") > -1);
    });

    it('Should resolve dev dependencies in a package with symlinked modules', function(){
        const dir = path.join(__dirname, 'input/package2');
        const syncignore = new syncfile.SyncIgnore(dir);
        const packages = syncignore.exec(true);
        assert(packages.length === 9);
        assert(packages.indexOf("/node_modules/devA") > -1);
        assert(packages.indexOf("/node_modules/package1/node_modules/@jibo/dev1") > -1);
        assert(packages.indexOf("/node_modules/package1/node_modules/@jibo/dev1-1") > -1);
        assert(packages.indexOf("/node_modules/package1/node_modules/@jibo/dev1-2") > -1);
        assert(packages.indexOf("/node_modules/package1/node_modules/@jibo/dev1-prod1") > -1);
        assert(packages.indexOf("/node_modules/package1/node_modules/@jibo/dev2") > -1);
        assert(packages.indexOf("/node_modules/package1/node_modules/@jibo/dev2-1") > -1);
        assert(packages.indexOf("/node_modules/package1/node_modules/@jibo/dev2-prod1") > -1);
        assert(packages.indexOf("/node_modules/package1/node_modules/@jibo/prod1-2-dev1") > -1);
    });
});
